new_js = r'''<script>
const D = {
  weekly: {
    labels: ["18–24 Nov","25 Nov–1 Dec","2–8 Dec","9–15 Dec","16–22 Dec","23–29 Dec"],
    exp: [1245,1350,1463,1513,1644,1772],
