  }
};

const C = { exp:"#1f6f68", ctl:"#9aa5a0", ink:"#13211d", soft:"#75847f", line:"#e6e4dc", alert:"#b23a48" };
const FONT = '-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif';

function svgEl(w,h,body){
  return '<svg viewBox="0 0 '+w+' '+h+'" role="img" preserveAspectRatio="xMidYMid meet">'+body+'</svg>';
}
function txt(x,y,s,o){
  o = o || {};
  return '<text x="'+x+'" y="'+y+'" font-family="'+(o.family||FONT)+
    '" font-size="'+(o.size||11)+'" fill="'+(o.fill||C.soft)+'" text-anchor="'+(o.anchor||'start')+
