}

/* ---------- weekly grouped bars ---------- */
(function(){
  const W=520,H=320,m={t:34,r:14,b:44,l:46};
  const data=D.weekly, max=2000;
  const iw=W-m.l-m.r, ih=H-m.t-m.b;
  const y=v=>m.t+ih-(v/max)*ih;
  let s='';
  [0,500,1000,1500,2000].forEach(g=>{
    s+='<line x1="'+m.l+'" x2="'+(W-m.r)+'" y1="'+y(g)+'" y2="'+y(g)+'" stroke="'+(g===0?C.ink:C.line)+'" stroke-width="1"/>';
    s+=txt(m.l-9,y(g)+4,String(g),{anchor:'end',size:10});
  });
  const cw=iw/data.labels.length, bw=21, gap=7;
  data.labels.forEach((lab,i)=>{
    const cx=m.l+cw*i+cw/2;
    const e=data.exp[i], c=data.ctl[i];
    s+='<rect x="'+(cx-bw-gap/2)+'" y="'+y(e)+'" width="'+bw+'" height="'+(m.t+ih-y(e))+'" fill="'+C.exp+'" rx="2"/>';
    s+='<rect x="'+(cx+gap/2)+'" y="'+y(c)+'" width="'+bw+'" height="'+(m.t+ih-y(c))+'" fill="'+C.ctl+'" rx="2"/>';
