  s+=txt(c5,y(tot(5))-10,tot(5).toLocaleString(),{anchor:'middle',size:11,fill:C.ink,weight:700});
  s+=txt(c5,y(tot(5))-24,'week total',{anchor:'middle',size:8.6,ls:.06});
  document.getElementById('chart-weekly').innerHTML=svgEl(W,H,s);
})();

/* ---------- wait distribution horizontal bars ---------- */
(function(){
  const W=520,H=380,m={t:6,r:62,b:30,l:80};
  const data=D.waitbins, max=30;
