    s+='<line x1="'+x(Math.min(e,c))+'" x2="'+x(Math.max(e,c))+'" y1="'+cy+'" y2="'+cy+'" stroke="'+(isBad?'#e8b9be':'#cfd6d3')+'" stroke-width="3.5" stroke-linecap="round"/>';
    s+='<circle cx="'+x(c)+'" cy="'+cy+'" r="6.5" fill="'+C.ctl+'" stroke="#fff" stroke-width="1.6"/>';
    s+='<circle cx="'+x(e)+'" cy="'+cy+'" r="6.5" fill="'+(isBad?C.alert:C.exp)+'" stroke="#fff" stroke-width="1.6"/>';
  });
  document.getElementById(id).innerHTML=svgEl(W,H,s);
}
dumbbell('chart-dept-comp', D.dept.comp_exp, D.dept.comp_ctl, 78, 93, [80,84,88,92], v=>v+'%');
dumbbell('chart-dept-lost', D.dept.lost_exp, D.dept.lost_ctl, 0, 14, [0,4,8,12], v=>v+'%');

/* ---------- derm line ---------- */
(function(){
  const W=520,H=310,m={t:18,r:66,b:44,l:46};
  const data=D.derm, lo=74, hi=90;
  const iw=W-m.l-m.r, ih=H-m.t-m.b;
  const x=i=>m.l+(iw/(data.labels.length-1))*i;
