    let d='';
    arr.forEach((v,i)=>{ d+=(i?'L':'M')+x(i)+' '+y(v); });
    return '<path d="'+d+'" fill="none" stroke="'+col+'" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>';
  };
  s+=line(data.ctl,C.ctl);
  s+=line(data.exp,C.exp);
  data.exp.forEach((v,i)=>{ s+='<circle cx="'+x(i)+'" cy="'+y(v)+'" r="4.6" fill="'+C.exp+'" stroke="#fff" stroke-width="1.6"/>'; });
  data.ctl.forEach((v,i)=>{ s+='<circle cx="'+x(i)+'" cy="'+y(v)+'" r="4.6" fill="'+C.ctl+'" stroke="#fff" stroke-width="1.6"/>'; });
  s+=txt(x(data.labels.length-1)+11,y(data.exp[data.exp.length-1])+4,'79.4%',{size:10.5,fill:C.exp,weight:700});
  s+=txt(x(data.labels.length-1)+11,y(data.ctl[data.ctl.length-1])+4,'83.7%',{size:10.5,fill:C.soft,weight:700});
  data.labels.forEach((lab,i)=>{
    s+=txt(x(i),H-16,lab,{anchor:i===0?'start':(i===data.labels.length-1?'end':'middle'),size:9.2});
  });
  document.getElementById('chart-derm').innerHTML=svgEl(W,H,s);
})();

/* ---------- dept table ---------- */
(function(){
  const d=D.dept, rows=[];
  for(let i=0;i<d.labels.length;i++){
    const gap=d.comp_exp[i]-d.comp_ctl[i];
