      '<td>'+d.labels[i]+'</td>'+
      '<td>'+d.n_exp[i].toLocaleString()+' / '+d.n_ctl[i].toLocaleString()+'</td>'+
      '<td>'+d.comp_exp[i].toFixed(2)+'%</td>'+
      '<td>'+d.comp_ctl[i].toFixed(2)+'%</td>'+
