      '<td>'+d.lost_exp[i].toFixed(2)+'%</td>'+
      '<td>'+d.lost_ctl[i].toFixed(2)+'%</td>'+
      '<td>'+d.wait_exp[i]+' / '+d.wait_ctl[i]+'</td>'+
      '</tr>'
    );
  }
  document.getElementById('dept-table').innerHTML=rows.join('');
})();
</script>'''
